// SPDX-License-Identifier: MIT
// Lumenpath Refraction (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/lumenpath.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "lumenpath:<seed>:<difficulty>"), so the same seed is the same lattice as the Python game.
// Byte parity goes through engines/unreal/core-test/lumenpath_parity.txt (lumenpath_core_test.cpp), generated by
// tools/minigames/lumenpath_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <set>
#include <string>
#include <utility>
#include <vector>

namespace daedalus { namespace lumenpath {

inline const char* GameId() { return "lumenpath"; }
inline const char* Title() { return "Lumenpath Refraction"; }

struct Difficulty { const char* Name; int Size; int Crystals; int Stones; int Moves; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 5, 2, 0, 12 }, { "normal", 6, 3, 2, 10 }, { "hard", 7, 4, 4, 9 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

constexpr int BoonDelta = 1;  // Spirit Boon (Sky Lark Spirit): moves +1 per level (hephaestus R2-9; level 2 = 5+ summons)
/** FindDifficulty with a Spirit Boon level 0..2 applied to Moves (PrismGame boon, floor 0). Nullptr on a bad level. */
inline const Difficulty* FindDifficulty(const std::string& Name, int Boon)
{
	if (Boon == 0) return FindDifficulty(Name);
	if (Boon < 0 || Boon > 2) return nullptr;
	struct Boosted { Difficulty Table[2][DifficultyCount]; };
	static const Boosted B = [] {
		Boosted Out{};
		for (int L = 0; L < 2; ++L)
			for (int I = 0; I < DifficultyCount; ++I)
			{
				Out.Table[L][I] = Difficulties()[I];
				Out.Table[L][I].Moves = std::max(0, Out.Table[L][I].Moves + BoonDelta * (L + 1));
			}
		return Out;
	}();
	for (int I = 0; I < DifficultyCount; ++I)
	{
		if (Name == B.Table[Boon - 1][I].Name) return &B.Table[Boon - 1][I];
	}
	return nullptr;
}

// Cells: '.' empty, '/' and '\\' mirrors, '*' crystal, '#' cracked stone. Directions E W N S as in the Python.
enum class Dir : int { E = 0, W, N, S };
inline Dir Turn(char Mirror, Dir D)
{
	if (Mirror == '/') { switch (D) { case Dir::E: return Dir::N; case Dir::N: return Dir::E; case Dir::W: return Dir::S; default: return Dir::W; } }
	switch (D) { case Dir::E: return Dir::S; case Dir::S: return Dir::E; case Dir::W: return Dir::N; default: return Dir::W; }
}
inline void Step(Dir D, int& R, int& C) { switch (D) { case Dir::E: ++C; break; case Dir::W: --C; break; case Dir::N: --R; break; default: ++R; } }
inline char Cycle(char Cell) { return Cell == '.' ? '/' : Cell == '/' ? '\\' : '.'; }

using Cell = std::pair<int, int>;

/** Cells the beam visits, in order, from the west edge at SourceRow (lumenpath.trace). */
inline std::vector<Cell> Trace(const std::vector<std::string>& Grid, int SourceRow)
{
	const int N = static_cast<int>(Grid.size());
	int R = SourceRow, C = 0; Dir D = Dir::E;
	std::set<std::tuple<int, int, int>> Seen; std::vector<Cell> Path;
	while (R >= 0 && R < N && C >= 0 && C < N && !Seen.count({ R, C, static_cast<int>(D) }))
	{
		Seen.insert({ R, C, static_cast<int>(D) });
		const char Ch = Grid[static_cast<size_t>(R)][static_cast<size_t>(C)];
		if (Ch == '#') break;
		Path.push_back({ R, C });
		if (Ch == '/' || Ch == '\\') D = Turn(Ch, D);
		Step(D, R, C);
	}
	return Path;
}

struct Mirror { int R, C; char M; };

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<std::string> Grid;
	int SourceRow = 0;
	std::vector<Cell> Crystals;    // sorted, as Python keeps them
	std::vector<Mirror> Solution;  // the generating mirrors
	int Moves = 0, Lit = 0, Best = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int Size() const { return static_cast<int>(Grid.size()); }

	int CountLit() const
	{
		const std::vector<Cell> On = Trace(Grid, SourceRow);
		const std::set<Cell> OnSet(On.begin(), On.end());
		int Count = 0; for (const Cell& K : Crystals) if (OnSet.count(K)) ++Count;
		return Count;
	}

	/** PrismGame.start + Game.setup. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName, int Boon = 0)
	{
		Diff = FindDifficulty(DifficultyName, Boon);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Setup();
		return true;
	}

	void Setup()
	{
		const int N = Diff->Size;
		std::vector<std::string> Draft; std::vector<Mirror> Mirrors; std::vector<Cell> Path; int Src = 0;
		std::vector<Cell> Free;
		while (true)
		{
			Draft.assign(static_cast<size_t>(N), std::string(static_cast<size_t>(N), '.'));
			Src = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(N)));
			int R = Src, C = 0; Dir D = Dir::E; Mirrors.clear(); Path.clear();
			while (R >= 0 && R < N && C >= 0 && C < N && std::find(Path.begin(), Path.end(), Cell{ R, C }) == Path.end())
			{
				Path.push_back({ R, C });
				if (C > 0 && Rng.RandomDouble() < 0.35 && static_cast<int>(Mirrors.size()) < N)
				{
					const char M = Rng.ChoiceIndex(2) == 0 ? '/' : '\\';
					Draft[static_cast<size_t>(R)][static_cast<size_t>(C)] = M;
					Mirrors.push_back({ R, C, M });
					D = Turn(M, D);
				}
				Step(D, R, C);
			}
			if (!(R >= 0 && R < N && C >= 0 && C < N))
			{
				Free.clear();
				for (const Cell& P : Path) if (Draft[static_cast<size_t>(P.first)][static_cast<size_t>(P.second)] == '.') Free.push_back(P);
				if (static_cast<int>(Free.size()) >= Diff->Crystals && !Mirrors.empty()) break;
			}
		}
		std::vector<Cell> Picked;
		for (std::size_t I : Rng.SampleIndices(Free.size(), static_cast<size_t>(Diff->Crystals))) Picked.push_back(Free[I]);
		std::sort(Picked.begin(), Picked.end());
		std::vector<std::string> Clean(static_cast<size_t>(N), std::string(static_cast<size_t>(N), '.'));
		for (const Cell& K : Picked) Clean[static_cast<size_t>(K.first)][static_cast<size_t>(K.second)] = '*';
		std::vector<Cell> Others;
		for (int I = 0; I < N; ++I) for (int J = 0; J < N; ++J) if (std::find(Path.begin(), Path.end(), Cell{ I, J }) == Path.end()) Others.push_back({ I, J });
		const size_t StoneCount = std::min(static_cast<size_t>(Diff->Stones), Others.size());
		for (std::size_t I : Rng.SampleIndices(Others.size(), StoneCount)) Clean[static_cast<size_t>(Others[I].first)][static_cast<size_t>(Others[I].second)] = '#';
		Grid = Clean; SourceRow = Src; Crystals = Picked; Solution = Mirrors;
		int Cost = 0; for (const Mirror& M : Mirrors) Cost += (M.M == '/' ? 1 : 2);
		Moves = std::max(Diff->Moves, Cost);
		Lit = CountLit(); Best = Lit;
		if (Lit == static_cast<int>(Crystals.size())) Setup();   // already solved without mirrors: draw again
	}

	enum class Act : int { Ok = 0, GameOver, BadCell };

	/** Toggle the mirror at (R, C). `Gained` receives this move's points. Mirrors lumenpath.Game.act. */
	Act Toggle(int R, int C, int& Gained)
	{
		Gained = 0;
		if (Over) return Act::GameOver;
		const int N = Size();
		if (R < 0 || R >= N || C < 0 || C >= N) return Act::BadCell;
		char& Ch = Grid[static_cast<size_t>(R)][static_cast<size_t>(C)];
		if (Ch == '*' || Ch == '#') return Act::BadCell;
		Ch = Cycle(Ch);
		--Moves;
		Lit = CountLit();
		Gained = 10 * std::max(0, Lit - Best);
		Best = std::max(Best, Lit);
		if (Lit == static_cast<int>(Crystals.size())) { Gained += 20 * Moves; Score += Gained; Over = true; Won = true; }
		else { Score += Gained; if (Moves <= 0) { Over = true; Won = false; } }
		return Act::Ok;
	}

	/** lumenpath.Game.demo_action: the first solution mirror not yet set, else the first toggleable cell. */
	Cell DemoAction() const
	{
		for (const Mirror& M : Solution) if (Grid[static_cast<size_t>(M.R)][static_cast<size_t>(M.C)] != M.M) return { M.R, M.C };
		const int N = Size();
		for (int I = 0; I < N; ++I) for (int J = 0; J < N; ++J) { const char Ch = Grid[static_cast<size_t>(I)][static_cast<size_t>(J)]; if (Ch == '.' || Ch == '/' || Ch == '\\') return { I, J }; }
		return { 0, 0 };
	}

	std::string GridString() const { std::string S; for (size_t I = 0; I < Grid.size(); ++I) { if (I) S.push_back('|'); S += Grid[I]; } return S; }
};

} } // namespace daedalus::lumenpath
